// n8n Code Node: Format session approval as Slack-compatible mrkdwn
// Input: expects a single item with session data, jobs, opportunities, and base_url
// base_url should be the app URL, e.g. "https://pidgeon-head.example.com"

const session = $("get_session").first().json;
const project = $("get_project").first().json;

const participantName = session.participant_name || "Unknown";
const usingFor = session.using_n8n_for || "";
const profileSummary = session.profile_summary || "";
const sessionSummary = session.session_summary || "";
const technicalAbility = session.technical_ability || "";
const projectType = project.type || "discovery_interview";
const jobs =
  $("get_jobs")
    .all()
    .map((o) => o.json) || [];
const opportunities =
  $("get_opps")
    .all()
    .map((o) => o.json) || [];
const baseUrl = session.base_url || "https://pidgeonhead.netlify.app";
const sessionUrl = `${baseUrl}/sessions/${session.id}`;
const scriptUrl = `${baseUrl}/projects/${project.id}/script`;
const created = new Date($("find_file").first().json.createdTime);

const formattedDate = `${String(created.getDate()).padStart(2, "0")}/${String(created.getMonth() + 1).padStart(2, "0")}/${String(created.getFullYear()).slice(-2)}`;

const lines = [];

function capitalizeFirstLetter(val) {
  return String(val).charAt(0).toUpperCase() + String(val).slice(1);
}

// Profile
lines.push(
  `*${participantName} (${usingFor === "Never used before" ? "Never used n8n before" : `Using n8n for ${usingFor}`})*`,
);
lines.push(
  `${capitalizeFirstLetter(project.name)} – ${formattedDate}`,
);
lines.push("");

// Key takeaway placeholder
lines.push("*Key Takeaway*");
lines.push("_Add your key takeaway here..._");
lines.push("");

if (profileSummary) {
  lines.push(`*Profile*`);
  lines.push(profileSummary);
  lines.push("");
}

// Technical ability
if (technicalAbility) {
  lines.push(`*Technical Ability*`);
  lines.push(technicalAbility);
  lines.push("");
}

if (projectType === "usability_test") {
  // Usability test: Script link → Session summary → Opportunities (no Jobs)
  lines.push(`<${scriptUrl}|*Script*>`);
  lines.push("");

  if (sessionSummary) {
    lines.push(`*Session Summary*`);
    lines.push(sessionSummary);
    lines.push("");
  }

  if (opportunities.length) {
    lines.push(
      `<${sessionUrl}?tab=opportunities|*Opportunities*> (${opportunities.length})`,
    );
    for (const opp of opportunities) {
      lines.push(`• ${opp.content}`);
    }
    lines.push("");
  }
} else {
  // Discovery interview: Jobs → Opportunities
  if (jobs.length) {
    lines.push(`<${sessionUrl}?tab=jtbd|*Jobs to be Done*> (${jobs.length})`);
    for (const job of jobs) {
      lines.push(`• _${job.content}_`);
    }
    lines.push("");
  }

  if (opportunities.length) {
    lines.push(
      `<${sessionUrl}?tab=opportunities|*Opportunities*> (${opportunities.length})`,
    );
    for (const opp of opportunities) {
      lines.push(`• ${opp.content}`);
    }
    lines.push("");
  }
}

let text = lines.join("\n");

// Extract the interview technique review from the technique_review agent as a separate field
let techniqueReview = "";
try {
  techniqueReview = $("technique_review").first().json.output || "";
} catch (e) {
  techniqueReview = "";
}

return [{ json: { text, techniqueReview } }];
